/* Back follows the screens inside a dialog; X closes it. */
let dialogRoute=null,dialogTrail=[],dialogRouteScope='',replayingDialog=false;
function dialogUserScope(){return [role,agency,typeof activeMember==='undefined'?'':activeMember,role==='tenant'?tenant:''].join(':')}
function sameDialogRoute(a,b){return JSON.stringify(a)===JSON.stringify(b)}
function enterDialogRoute(route){const scope=dialogUserScope();if(scope!==dialogRouteScope||!modal.open){dialogRouteScope=scope;dialogTrail=[];dialogRoute=null}if(!replayingDialog&&dialogRoute&&!sameDialogRoute(dialogRoute,route))dialogTrail.push({...dialogRoute});dialogRoute={...route}}
function dialogRouteLabel(route){return route?.type==='job'?({comments:'Comments',schedule:'Attendance',quotes:'Quotes',invoices:'Invoices',history:'Timeline',report:'Report',finance:'Private costs'}[route.section]||'job'):route?.type==='booking'?'appointment':route?.type==='payments'?'Payments / POP':route?.type==='invoicePreview'?'invoice preview':'previous screen'}
function decorateDialogBack(){modal.querySelectorAll('.back-link').forEach(button=>button.remove());const previous=dialogTrail.at(-1),label=previous?'← Back to '+dialogRouteLabel(previous):'← Back to '+(view==='calendar'?'calendar':view==='planner'?'planner':'jobs');modal.insertAdjacentHTML('afterbegin',`<button class="back-link" type="button" onclick="dialogBack()">${esc(label)}</button>`)}
function showDialogRoute(route){if(!route||dialogUserScope()!==dialogRouteScope){modal.close();return}replayingDialog=true;try{if(route.type==='job')jobDetail(route.jid,route.section);else if(route.type==='booking')privateBookingDetail(route.bid);else if(route.type==='payments')paymentDetails(route.jid,route.iid);else if(route.type==='invoicePreview')invoicePreview(route.jid,route.iid)}finally{replayingDialog=false}}
function dialogBack(){if(dialogUserScope()!==dialogRouteScope){dialogTrail=[];dialogRoute=null;modal.close();return}const previous=dialogTrail.pop();if(previous)showDialogRoute(previous);else{dialogRoute=null;modal.close()}}
const detailBeforeDialogNavigation=jobDetail;jobDetail=function(jid,section='comments'){if(!getJob(jid))return detailBeforeDialogNavigation(jid,section);enterDialogRoute({type:'job',jid,section});detailBeforeDialogNavigation(jid,section);decorateDialogBack()};
const bookingBeforeDialogNavigation=privateBookingDetail;privateBookingDetail=function(bid){if(role!=='sevlink')return;enterDialogRoute({type:'booking',bid});bookingBeforeDialogNavigation(bid);decorateDialogBack()};
const paymentsBeforeDialogNavigation=paymentDetails;paymentDetails=function(jid,iid){if(role==='tenant'||!findInvoice(jid,iid))return;enterDialogRoute({type:'payments',jid,iid});paymentsBeforeDialogNavigation(jid,iid);decorateDialogBack()};
const previewBeforeDialogNavigation=invoicePreview;invoicePreview=function(jid,iid){if(role==='tenant'||!findInvoice(jid,iid))return;enterDialogRoute({type:'invoicePreview',jid,iid});previewBeforeDialogNavigation(jid,iid);decorateDialogBack()};
const formBeforeDialogNavigation=openForm;openForm=function(title,content,submit,handler){if(!modal.open){dialogRoute=null;dialogTrail=[];dialogRouteScope=dialogUserScope()}const parent=modal.open&&dialogUserScope()===dialogRouteScope?dialogRoute:null;formBeforeDialogNavigation(title,content,submit,handler);let dirty=false;$('#form')?.addEventListener?.('input',()=>dirty=true);if($('#formBack'))$('#formBack').onclick=()=>{if(dirty&&!confirm('Discard the unsaved changes in this form?'))return;if(parent)showDialogRoute(parent);else modal.close()}};

